// FILE: client/src/pages/LoginPage.jsx
"use strict";

import React, { useEffect, useRef, useState } from "react";
import userApi from "../services/user.api";
import Loading from "../components/common/Loading";
import ErrorMessage from "../components/common/ErrorMessage";
import EmptyState from "../components/common/EmptyState";

const LOGIN_REFERENCE_IMAGE =
  "data:image/png;base64,";

/**
 * =====================================================
 * 🔥 LOGIN PAGE
 * ✔ 로그인 후 관리자 진입 무한로딩 방지
 * ✔ token/session/localStorage 동기화
 * ✔ redirect 중복 방지
 * ✔ 관리자 JWT만 adminToken 저장
 * ✔ 일반 사용자 JWT의 관리자 토큰 오염 방지
 * ✔ 관리자 / 일반 사용자 로그인 저장소 분리
 * ✔ fallback 구조 유지
 * ✔ 가짜 local-admin 토큰 생성 방지
 * ✔ /admin 접속 시 자동 대시보드 이동 방지
 * ✔ 기존 구조 유지
 * ✔ 회원가입 버튼 → 약관동의 페이지 이동
 * =====================================================
 */

function LoginPage({ navigate, setUser }) {
  const autoCheckedRef = useRef(false);
  const redirectLockRef = useRef(false);
  const loginLockRef = useRef(false);

  const [id, setId] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [checked, setChecked] = useState(false);
  const [redirecting, setRedirecting] = useState(false);

  const isAdminLoginPath = () => {
    try {
      const pathname = String(window.location.pathname || "");

      return (
        pathname === "/admin" ||
        pathname.startsWith("/admin/")
      );
    } catch {
      return false;
    }
  };

  const go = (path) => {
    try {
      if (window.location.pathname === path) return;

      if (typeof navigate === "function") {
        navigate(path);
        return;
      }

      window.history.pushState({}, "", path);
      window.dispatchEvent(new PopStateEvent("popstate"));
    } catch {
      window.location.href = path;
    }
  };

  const decodeTokenPayload = (token) => {
    try {
      const safeToken = String(token || "")
        .replace(/^Bearer\s+/i, "")
        .trim();

      const payload = safeToken.split(".")[1];

      if (!payload) {
        return null;
      }

      const normalized = payload
        .replace(/-/g, "+")
        .replace(/_/g, "/");

      const padded =
        normalized +
        "=".repeat((4 - (normalized.length % 4)) % 4);

      return JSON.parse(
        decodeURIComponent(
          atob(padded)
            .split("")
            .map(
              (char) =>
                `%${char
                  .charCodeAt(0)
                  .toString(16)
                  .padStart(2, "0")}`
            )
            .join("")
        )
      );
    } catch {
      return null;
    }
  };

  const isAdminToken = (token) => {
    const payload = decodeTokenPayload(token);

    const role = String(payload?.role || "")
      .trim()
      .toLowerCase();

    return (
      payload?.isAdmin === true ||
      role === "admin" ||
      role === "superadmin" ||
      role === "super_admin"
    );
  };

  const getSavedToken = () => {
    const adminLogin = isAdminLoginPath();

    const candidates = (
      adminLogin
        ? [
            localStorage.getItem("adminToken"),
            localStorage.getItem("local-admin-token"),
            sessionStorage.getItem("adminToken"),
            sessionStorage.getItem("local-admin-token"),
          ]
        : [
            localStorage.getItem("token"),
            localStorage.getItem("accessToken"),
            localStorage.getItem("authToken"),
            localStorage.getItem("jwt"),
            sessionStorage.getItem("token"),
            sessionStorage.getItem("accessToken"),
            sessionStorage.getItem("authToken"),
            sessionStorage.getItem("jwt"),
          ]
    ).filter(
      (token) =>
        token &&
        token !== "undefined" &&
        token !== "null" &&
        String(token).trim().length >= 5
    );

    if (adminLogin) {
      const adminToken =
        candidates.find((token) => isAdminToken(token)) || "";

      return adminToken
        ? String(adminToken).replace(/^Bearer\s+/i, "").trim()
        : "";
    }

    const userToken =
      candidates.find((token) => !isAdminToken(token)) || "";

    return userToken
      ? String(userToken).replace(/^Bearer\s+/i, "").trim()
      : "";
  };

  const clearAdminContaminatedUserAuth = () => {
    try {
      [
        "token",
        "accessToken",
        "authToken",
        "jwt",
      ].forEach((key) => {
        const localValue =
          localStorage.getItem(key);

        const sessionValue =
          sessionStorage.getItem(key);

        if (isAdminToken(localValue)) {
          localStorage.removeItem(key);
        }

        if (isAdminToken(sessionValue)) {
          sessionStorage.removeItem(key);
        }
      });

      [
        {
          storage: localStorage,
          key: "user",
        },
        {
          storage: sessionStorage,
          key: "user",
        },
      ].forEach(({ storage, key }) => {
        try {
          const saved =
            JSON.parse(
              storage.getItem(key) || "null"
            );

          const role =
            String(
              saved?.role ||
              saved?.userRole ||
              saved?.type ||
              ""
            )
              .trim()
              .toLowerCase();

          const adminUser =
            saved?.isAdmin === true ||
            role === "admin" ||
            role === "superadmin" ||
            role === "super_admin";

          if (adminUser) {
            storage.removeItem(key);
          }
        } catch {
          storage.removeItem(key);
        }
      });
    } catch (e) {
      console.warn(
        "ADMIN CONTAMINATED USER AUTH CLEAR ERROR:",
        e?.message || e
      );
    }
  };

  useEffect(() => {
    if (autoCheckedRef.current) return;

    autoCheckedRef.current = true;

    try {
      setChecked(true);
    } catch (e) {
      console.warn("AUTO LOGIN FAIL", e);
      setChecked(true);
    }
  }, []);

  const saveAuth = (token, user) => {
    const safeToken = String(token || "")
      .replace(/^Bearer\s+/i, "")
      .trim();

    if (!safeToken) {
      throw new Error("TOKEN_SAVE_FAILED");
    }

    const payload = decodeTokenPayload(safeToken) || {};

    const actualRole = String(
      payload?.role ||
        user?.role ||
        user?.userRole ||
        user?.type ||
        "user"
    ).trim();

    const normalizedRole =
      actualRole === "super_admin" || actualRole === "superadmin"
        ? "superAdmin"
        : actualRole;

    const actualIsAdmin =
      payload?.isAdmin === true ||
      user?.isAdmin === true ||
      normalizedRole === "admin" ||
      normalizedRole === "superAdmin";

    const normalizedUser = {
      ...user,
      role: normalizedRole,
      userRole: user?.userRole || normalizedRole,
      type: user?.type || normalizedRole,
      isAdmin: actualIsAdmin,
    };

    const adminLogin =
      isAdminLoginPath();

    if (adminLogin) {
      if (
        !actualIsAdmin ||
        !isAdminToken(safeToken)
      ) {
        throw new Error(
          "관리자 권한이 필요합니다."
        );
      }

      clearAdminContaminatedUserAuth();

      [
        "adminToken",
        "local-admin-token",
      ].forEach((key) => {
        localStorage.setItem(
          key,
          safeToken
        );

        sessionStorage.setItem(
          key,
          safeToken
        );
      });

      localStorage.setItem(
        "adminUser",
        JSON.stringify(normalizedUser)
      );

      sessionStorage.setItem(
        "adminUser",
        JSON.stringify(normalizedUser)
      );

      localStorage.setItem(
        "isAdmin",
        "true"
      );

      sessionStorage.setItem(
        "isAdmin",
        "true"
      );

      localStorage.setItem(
        "adminLoggedIn",
        "true"
      );

      sessionStorage.setItem(
        "adminLoggedIn",
        "true"
      );
    } else {
      if (
        actualIsAdmin ||
        isAdminToken(safeToken)
      ) {
        throw new Error(
          "일반 사용자 로그인 페이지입니다."
        );
      }

      localStorage.removeItem(
        "nora_user_logged_out"
      );
      sessionStorage.removeItem(
        "nora_user_logged_out"
      );

      [
        "token",
        "accessToken",
        "authToken",
        "jwt",
      ].forEach((key) => {
        localStorage.setItem(
          key,
          safeToken
        );

        sessionStorage.setItem(
          key,
          safeToken
        );
      });

      localStorage.setItem(
        "user",
        JSON.stringify(normalizedUser)
      );

      sessionStorage.setItem(
        "user",
        JSON.stringify(normalizedUser)
      );
    }

    if (typeof setUser === "function") {
      setUser(normalizedUser);
    }

    try {
      window.dispatchEvent(
        new Event("auth-updated")
      );
    } catch (e) {
      console.warn(
        "AUTH UPDATED EVENT FAIL:",
        e?.message || e
      );
    }
  };

  const handleFallbackLogin = async () => {
    try {
      if (!isAdminLoginPath()) {
        throw new Error(
          "로그인 토큰이 없습니다."
        );
      }

      const savedAdminToken =
        [
          localStorage.getItem("adminToken"),
          sessionStorage.getItem("adminToken"),
          localStorage.getItem("local-admin-token"),
          sessionStorage.getItem("local-admin-token"),
        ].find((token) => isAdminToken(token)) || "";

      if (!savedAdminToken) {
        throw new Error("관리자 인증 토큰 없음");
      }

      const payload = decodeTokenPayload(savedAdminToken) || {};

      const localUser = {
        id:
          payload?.id ||
          payload?.userId ||
          id ||
          "admin",
        role: payload?.role || "admin",
        userRole: payload?.role || "admin",
        type: payload?.role || "admin",
        isAdmin: true,
        localFallback: true,
      };

      saveAuth(savedAdminToken, localUser);

      const saved = getSavedToken();

      if (!saved) {
        throw new Error("TOKEN_SAVE_FAILED");
      }

      if (redirectLockRef.current) return;

      redirectLockRef.current = true;
      setRedirecting(true);
      window.location.assign("/admin/dashboard");
    } catch (e) {
      console.error("FALLBACK LOGIN ERROR:", e);
      setError(
        e?.message ||
          "로그인 실패"
      );
      setRedirecting(false);
    }
  };

  const handleLogin = async () => {
    if (loginLockRef.current) return;

    if (!id || !password) {
      setError("아이디와 비밀번호를 입력하세요");
      return;
    }

    try {
      loginLockRef.current = true;
      setLoading(true);
      setError("");

      let res = null;

      try {
        res = await Promise.race([
          userApi.login({ id, password }),
          new Promise((_, reject) =>
            setTimeout(
              () => reject(new Error("LOGIN_TIMEOUT")),
              5000
            )
          ),
        ]);
      } catch (apiError) {
        console.error("API LOGIN FAIL:", apiError);
        throw apiError;
      }

      console.log("LOGIN RESPONSE:", res);

      const token =
        res?.adminToken ||
        res?.token ||
        res?.accessToken ||
        res?.authToken ||
        res?.jwt ||
        res?.data?.adminToken ||
        res?.data?.token ||
        res?.data?.accessToken ||
        res?.data?.authToken ||
        res?.data?.jwt ||
        res?.data?.data?.token ||
        res?.data?.data?.adminToken ||
        res?.access_token ||
        res?.data?.access_token ||
        res?.data?.data?.access_token;

      const user =
        res?.user ||
        res?.data?.user ||
        res?.data?.data?.user ||
        {};

      if (!token) {
        console.warn("⚠️ TOKEN 없음 → fallback login");

        if (isAdminLoginPath()) {
          await handleFallbackLogin();
          return;
        }

        throw new Error(
          "로그인 토큰이 없습니다."
        );
      }

      const adminLogin =
        isAdminLoginPath();

      if (
        adminLogin &&
        !isAdminToken(token)
      ) {
        throw new Error(
          "관리자 권한이 필요합니다."
        );
      }

      if (
        !adminLogin &&
        isAdminToken(token)
      ) {
        throw new Error(
          "일반 사용자 로그인 페이지입니다."
        );
      }

      saveAuth(token, user);

      const saved = getSavedToken();

      if (!saved) {
        throw new Error("TOKEN_SAVE_FAILED");
      }

      console.log("✅ TOKEN SAVE COMPLETE");

      if (redirectLockRef.current) return;

      redirectLockRef.current = true;
      setRedirecting(true);

      if (adminLogin) {
        window.location.assign(
          "/admin/dashboard"
        );
        return;
      }

      window.location.assign("/");
    } catch (e) {
      console.error("LOGIN ERROR:", e);
      const loginErrorMessage =
        e?.response?.data?.message ||
        e?.message ||
        "로그인 실패";

      setError(
        loginErrorMessage === "USER_NOT_FOUND"
          ? "사용자를 찾을 수 없습니다"
          : loginErrorMessage
      );
      setRedirecting(false);
    } finally {
      loginLockRef.current = false;

      if (!redirectLockRef.current) {
        setLoading(false);
      }
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleLogin();
    }
  };

  const handleSignup = () => {
    go("/signup-type");
  };

  const handleKakaoLogin = async () => {
    try {
      setLoading(true);
      setError("");

      const base =
        window.__ENV__?.API_BASE_URL ||
        "https://api.nora365.co.kr/api";

      const res = await fetch(
        `${base}/auth/kakao/login`
      );

      const data = await res.json();

      if (!data?.url) {
        throw new Error("카카오 URL 없음");
      }

      window.location.href = data.url;
    } catch {
      setError("카카오 로그인 실패");
    } finally {
      setLoading(false);
    }
  };

  if (loading || !checked || redirecting) {
    return <Loading message="로그인 처리 중..." />;
  }

  if (isAdminLoginPath()) {
    return (
      <div style={container}>
        <div style={card}>
          <h2 style={{ color: "#d4af37" }}>노마 로그인</h2>

          {error ? (
            <div style={{ marginBottom: 12 }}>
              <ErrorMessage message={error} />
            </div>
          ) : null}

          {!loading && checked && !error && false ? (
            <EmptyState />
          ) : null}

          <input
            placeholder="아이디"
            value={id}
            onChange={(e) => setId(e.target.value)}
            onKeyDown={handleKeyDown}
            style={input}
          />

          <input
            type="password"
            placeholder="비밀번호"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyDown={handleKeyDown}
            style={input}
          />

          <button
            onClick={handleLogin}
            style={loginBtn}
            disabled={loading || redirecting}
          >
            로그인
          </button>

          <button
            onClick={handleSignup}
            style={signupBtn}
            disabled={loading || redirecting}
          >
            회원가입
          </button>

          <hr style={{ margin: "20px 0", borderColor: "#333" }} />

          <button
            onClick={handleKakaoLogin}
            style={kakaoBtn}
            disabled={loading || redirecting}
          >
            카카오로 로그인
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="nora-reference-login-page">
      <style>{`
        html,
        body,
        #root {
          margin: 0;
          min-width: 100%;
          min-height: 100%;
          background: #000;
        }

        body {
          overflow-x: hidden;
        }

        .nora-reference-login-page {
          position: relative;
          width: 100vw;
          min-width: 320px;
          aspect-ratio: 1672 / 941;
          min-height: 100vh;
          overflow: hidden;
          background: #000;
          font-family: Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif;
        }

        .nora-reference-login-image {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          display: block;
          object-fit: fill;
          user-select: none;
          pointer-events: none;
        }

        /*
         * 기존 배경 이미지 안에 포함된 큰 로그인 패널 영역은 그대로 가리되,
         * 검정색 계통의 마스크 대신 좌우 주변 이미지를 자연스럽게 반사 확장한다.
         * 로그인 박스 크기/위치와 로그인 로직/API/상태/라우팅은 변경하지 않는다.
         */
        .nora-reference-login-original-mask {
          position: absolute;
          z-index: 1;
          left: 31.75%;
          top: 8.90%;
          width: 36.50%;
          height: 76.80%;
          overflow: hidden;
          pointer-events: none;
          background: transparent;
          box-shadow: none;
        }

        .nora-reference-login-original-mask::before,
        .nora-reference-login-original-mask::after {
          content: "";
          position: absolute;
          top: 0;
          width: 50%;
          height: 100%;
          background-image: url("${LOGIN_REFERENCE_IMAGE}");
          background-repeat: no-repeat;
          background-size: 547.9452% 130.2083%;
          background-position-y: 38.3693%;
          transform: scaleX(-1);
          pointer-events: none;
        }

        .nora-reference-login-original-mask::before {
          left: 0;
          background-position-x: 16.5141%;
        }

        .nora-reference-login-original-mask::after {
          right: 0;
          background-position-x: 83.4859%;
        }

        .nora-reference-login-compact {
          position: absolute;
          z-index: 2;
          left: 50%;
          top: 47.34%;
          width: 11cm;
          height: 15cm;
          max-width: calc(100vw - 24px);
          max-height: calc(100vh - 24px);
          transform: translate(-50%, -50%);
          overflow: hidden;
          border-radius: 14px;
        }

        .nora-reference-login-compact::after {
          content: "";
          position: absolute;
          z-index: 5;
          inset: 0;
          box-sizing: border-box;
          border: 3px solid rgba(212, 175, 55, 0.95);
          border-radius: 14px;
          pointer-events: none;
        }

        .nora-reference-login-compact-image {
          position: absolute;
          z-index: 0;
          left: -93.1507%;
          top: -13.3713%;
          width: 286.3014%;
          height: 133.8549%;
          display: block;
          object-fit: fill;
          user-select: none;
          pointer-events: none;
        }

        .nora-reference-login-input {
          position: absolute;
          z-index: 3;
          box-sizing: border-box;
          margin: 0;
          opacity: 1;
          pointer-events: auto;
          cursor: text;
          border: 0 !important;
          outline: 0 !important;
          border-radius: 0;
          color: #c8c1b4;
          caret-color: #f7d774;
          font-family: Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif;
          font-size: clamp(9px, 0.42cm, 16px);
          line-height: calc(1.389cm + 16px);
          font-weight: 500;
          letter-spacing: -0.02em;
          padding: 0 4.8%;
          background: transparent;
          box-shadow: none !important;
          -webkit-appearance: none;
          appearance: none;
          transition: none;
        }

        .nora-reference-login-input::placeholder {
          color: transparent;
        }

        .nora-reference-login-input:not(:placeholder-shown) {
          background:
            linear-gradient(
              rgba(15, 12, 8, 0.985),
              rgba(15, 12, 8, 0.985)
            )
            center / calc(100% - 14px) calc(100% - 18px) no-repeat;
        }

        .nora-reference-login-input:-webkit-autofill,
        .nora-reference-login-input:-webkit-autofill:hover,
        .nora-reference-login-input:-webkit-autofill:focus,
        .nora-reference-login-input:-webkit-autofill:active {
          -webkit-text-fill-color: #c8c1b4 !important;
          caret-color: #f7d774 !important;
          -webkit-box-shadow: 0 0 0 1000px rgba(15, 12, 8, 0.985) inset !important;
          box-shadow: 0 0 0 1000px rgba(15, 12, 8, 0.985) inset !important;
          border: 0 !important;
          outline: 0 !important;
        }

        .nora-reference-login-id {
          left: 18.65%;
          top: 51.50%;
          width: 70.43%;
          height: 9.26%;
        }

        .nora-reference-login-password {
          left: 18.65%;
          top: 62.31%;
          width: 70.43%;
          height: 9.26%;
        }

        .nora-reference-login-hit {
          position: absolute;
          z-index: 4;
          margin: 0;
          padding: 0;
          border: 0;
          outline: 0;
          background: transparent;
          color: transparent;
          cursor: pointer;
          -webkit-tap-highlight-color: transparent;
        }

        .nora-reference-login-button {
          left: 7.34%;
          top: 73.13%;
          width: 81.74%;
          height: 10.11%;
        }

        .nora-reference-signup-button {
          left: 7.34%;
          top: 84.29%;
          width: 81.74%;
          height: 9.26%;
        }

        .nora-reference-login-error {
          position: absolute;
          z-index: 10;
          left: 50%;
          top: 88px;
          width: min(520px, calc(100vw - 40px));
          transform: translateX(-50%);
          box-sizing: border-box;
          padding: 10px 14px;
          border: 1px solid rgba(212, 175, 55, 0.85);
          border-radius: 8px;
          background: rgba(6, 5, 4, 0.94);
          box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
        }

        @media (max-width: 760px) {
          .nora-reference-login-page {
            width: 100vw;
            min-height: auto;
            aspect-ratio: 1672 / 941;
          }

          .nora-reference-login-compact {
            width: min(11cm, calc(100vw - 20px));
            height: min(15cm, calc((100vw - 20px) * 15 / 11));
          }

          .nora-reference-login-input {
            font-size: clamp(7px, 2.9vw, 12px);
          }
        }
      `}</style>

      <img
        className="nora-reference-login-image"
        src={LOGIN_REFERENCE_IMAGE}
        alt="NORA 노라 마사지 노래방 로그인 페이지"
        draggable="false"
      />

      <div
        className="nora-reference-login-original-mask"
        aria-hidden="true"
      />

      {error ? (
        <div className="nora-reference-login-error">
          <ErrorMessage message={error} />
        </div>
      ) : null}

      {!loading && checked && !error && false ? <EmptyState /> : null}

      <div className="nora-reference-login-compact">
        <img
          className="nora-reference-login-compact-image"
          src={LOGIN_REFERENCE_IMAGE}
          alt=""
          aria-hidden="true"
          draggable="false"
        />

        <input
          className="nora-reference-login-input nora-reference-login-id"
          type="text"
          placeholder=" "
          aria-label="아이디"
          name="nora-login-id"
          autoComplete="off"
          spellCheck="false"
          value={id}
          onChange={(e) => setId(e.target.value)}
          onKeyDown={handleKeyDown}
        />

        <input
          className="nora-reference-login-input nora-reference-login-password"
          type="password"
          placeholder=" "
          aria-label="비밀번호"
          name="nora-login-password"
          autoComplete="new-password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={handleKeyDown}
        />

        <button
          type="button"
          className="nora-reference-login-hit nora-reference-login-button"
          aria-label="로그인"
          onClick={handleLogin}
          disabled={loading || redirecting}
        >
          로그인
        </button>

        <button
          type="button"
          className="nora-reference-login-hit nora-reference-signup-button"
          aria-label="회원가입"
          onClick={handleSignup}
          disabled={loading || redirecting}
        >
          회원가입
        </button>
      </div>
    </div>
  );
}

